<script setup lang="ts">
import { BookOpen, ClipboardCheck, GraduationCap, Library } from '@lucide/vue'; import type { Enrollment } from '~/types/domain'
defineProps<{ registrar?: boolean }>(); interface Data { total_students: number; programs: number; course_offerings: number; active_enrollments: number; recent_enrollments: Enrollment[] }
const { get } = useDashboard<Data>(); const { data } = await useAsyncData('management-dashboard', get)
const stats = computed(() => [{ label: 'Total Students', value: data.value?.total_students ?? 0, detail: 'All profiles', icon: GraduationCap }, { label: 'Programs', value: data.value?.programs ?? 0, detail: 'Academic programs', icon: Library }, { label: 'Course Offerings', value: data.value?.course_offerings ?? 0, detail: 'All terms', icon: BookOpen }, { label: 'Active Enrollments', value: data.value?.active_enrollments ?? 0, detail: 'Currently enrolled', icon: ClipboardCheck }])
</script>
<template><div class="space-y-6"><section aria-labelledby="academic-overview"><h2 id="academic-overview" class="mb-3 text-sm font-semibold text-[#29445f]">Academic overview</h2><div class="metric-grid grid sm:grid-cols-2 xl:grid-cols-4"><StatCard v-for="stat in stats" :key="stat.label" v-bind="stat" /></div></section><BaseCard><div class="mb-2 flex items-center justify-between"><h2 class="text-lg font-semibold tracking-[-0.02em] text-[#102a43]">Recent enrollments</h2><span class="text-xs font-medium text-[#77879b]">Latest activity</span></div><div v-for="enrollment in data?.recent_enrollments" :key="enrollment.id" class="flex items-center justify-between gap-4 border-t border-[#e5ecf3] py-3.5"><span class="font-medium text-[#29445f]">{{ enrollment.student?.first_name }} {{ enrollment.student?.last_name }}</span><StatusBadge :status="enrollment.status" /></div><p v-if="!data?.recent_enrollments?.length" class="border-t border-[#e5ecf3] py-8 text-center text-sm text-[#6b7d92]">New enrollments will appear here.</p></BaseCard></div></template>
